const input = $json.body ?? $json;
const required = ["event", "message_id", "conversation_id", "lead_id", "timestamp"];
const missing = required.filter(k => input[k] === undefined || input[k] === null || input[k] === "");
if (missing.length) return [{ json: { ok:false, error:{code:"INVALID_EVENT", message:"Required event fields are missing.", missing}, statusCode:400 } }];
if (input.event !== "MESSAGE_RECEIVED") return [{ json:{ok:false,error:{code:"INVALID_EVENT",message:"Unsupported event type.",event:input.event},statusCode:400} }];
return [{json:{ok:true,...input}}];

const m=$json.data || $json.message || $json;
const processed=Boolean(m.processed_at || m.processed === true || m.status === 'PROCESSED');
return [{json:{...$('Normalize Event').item.json,message:m,already_processed:processed}}];

const msg=$('Get Message').item.json.data || $('Get Message').item.json.message || $('Get Message').item.json;
const conv=$('Get Conversation').item.json.data || $('Get Conversation').item.json.conversation || $('Get Conversation').item.json;
const lead=$('Get Lead').item.json.data || $('Get Lead').item.json.lead || $('Get Lead').item.json;
const hr=$('Get Conversation History').item.json;
const history=Array.isArray(hr)?hr:(hr.messages||hr.data||[]);
const currentMessage=msg.message || msg.content || msg.text || '';
const relevantHistory=history.slice(-Number($env.N8N_CONTEXT_MESSAGE_LIMIT || 12));
const missing=[['transaction_type',lead.transaction_type],['property_type',lead.property_type],['location',lead.location],['budget',lead.budget_max ?? lead.budget_min],['bedrooms',lead.bedrooms],['timeline',lead.timeline],['contact',lead.email || lead.phone]].filter(([,v])=>v===null||v===undefined||v==='').map(([k])=>k);
return [{json:{...$('Normalize Event').item.json,current_message:currentMessage,conversation:conv,lead,history:relevantHistory,missing_fields:missing}}];

const r = $json;

/*
  MAYVEE Homes & Properties
  Parse + validate AI lead extraction.

  IMPORTANT:
  - Never invent missing lead information.
  - Invalid or unknown values become null.
  - Rule-based fallback extracts only explicitly stated facts.
*/

let raw =
  r.output_text ||
  r.text ||
  r.content ||
  r.response ||
  r.choices?.[0]?.message?.content ||
  r.choices?.[0]?.text;

// --------------------------------------------------
// Allowed MAYVEE values
// --------------------------------------------------

const allowedTransactionTypes = [
  'BUY',
  'RENT',
  'SELL',
  'BUILD',
  'INVEST',
  'ENQUIRY',
];

const allowedPropertyTypes = [
  'APARTMENT',
  'HOUSE',
  'LAND',
  'OFFICE',
  'SHOP',
  'COMMERCIAL',
  'OTHER',
];

const allowedTimelines = [
  'IMMEDIATELY',
  'WITHIN_1_MONTH',
  'WITHIN_3_MONTHS',
  'WITHIN_6_MONTHS',
  'RESEARCHING',
];

// --------------------------------------------------
// Helpers
// --------------------------------------------------

function cleanString(value) {
  if (value === null || value === undefined) return null;

  const str = String(value).trim();

  return str.length ? str : null;
}

function cleanEnum(value, allowed) {
  if (value === null || value === undefined) return null;

  const normalized = String(value)
    .trim()
    .toUpperCase();

  return allowed.includes(normalized)
    ? normalized
    : null;
}

function cleanNumber(value) {
  if (value === null || value === undefined || value === '') {
    return null;
  }

  const num = Number(value);

  return Number.isFinite(num)
    ? num
    : null;
}

function cleanInteger(value) {
  const num = cleanNumber(value);

  if (num === null) return null;

  return Number.isInteger(num)
    ? num
    : Math.round(num);
}

function cleanConfidence(value) {
  const num = Number(value);

  if (!Number.isFinite(num)) return 0;

  return Math.min(1, Math.max(0, num));
}

function normalizeExtraction(parsed) {
  return {
    transaction_type: cleanEnum(
      parsed.transaction_type,
      allowedTransactionTypes
    ),

    property_type: cleanEnum(
      parsed.property_type,
      allowedPropertyTypes
    ),

    bedrooms: cleanInteger(parsed.bedrooms),

    location: cleanString(parsed.location),

    budget_min: cleanNumber(parsed.budget_min),

    budget_max: cleanNumber(parsed.budget_max),

    currency: parsed.currency
      ? String(parsed.currency).trim().toUpperCase()
      : null,

    timeline: cleanEnum(
      parsed.timeline,
      allowedTimelines
    ),

    customer_name: cleanString(parsed.customer_name),

    email: cleanString(parsed.email),

    phone: cleanString(parsed.phone),

    confidence: cleanConfidence(parsed.confidence),
  };
}

// --------------------------------------------------
// Try AI JSON first
// --------------------------------------------------

try {
  if (typeof raw !== 'string') {
    raw = JSON.stringify(raw || {});
  }

  raw = raw
    .trim()
    .replace(/^```(?:json)?/i, '')
    .replace(/```$/i, '')
    .trim();

  const parsed = JSON.parse(raw);

  if (
    !parsed ||
    typeof parsed !== 'object' ||
    Array.isArray(parsed)
  ) {
    throw new Error('AI extraction was not a JSON object.');
  }

  const extraction = normalizeExtraction(parsed);

  return [
    {
      json: {
        ok: true,
        extraction,
        fallback_used: false,
      },
    },
  ];
} catch (error) {

  // --------------------------------------------------
  // Conservative rule-based fallback
  // --------------------------------------------------
  //
  // This fallback MUST NOT invent anything.
  // If the customer did not explicitly provide it,
  // leave it null.
  // --------------------------------------------------

  const norm = $('Normalize Event').item.json;

  const originalMessage =
    norm.current_message ||
    $('Get Message').item.json.content ||
    '';

  const msg = originalMessage.toLowerCase();

  // -------------------------
  // Transaction type
  // -------------------------

  let transactionType = null;

  if (
    /\b(build|develop|development|construct|construction)\b/i.test(msg)
  ) {
    transactionType = 'BUILD';
  } else if (
    /\b(invest|investment|investing)\b/i.test(msg)
  ) {
    transactionType = 'INVEST';
  } else if (
    /\b(buy|purchase|buying|purchase)\b/i.test(msg)
  ) {
    transactionType = 'BUY';
  } else if (
    /\b(rent|lease|renting)\b/i.test(msg)
  ) {
    transactionType = 'RENT';
  } else if (
    /\b(sell|selling|sale)\b/i.test(msg)
  ) {
    transactionType = 'SELL';
  }

  // -------------------------
  // Property type
  // -------------------------

  let propertyType = null;

  if (
    /\b(apartment|flat)\b/i.test(msg)
  ) {
    propertyType = 'APARTMENT';
  } else if (
    /\b(house|duplex|bungalow|detached|semi-detached|terrace|terraced)\b/i.test(msg)
  ) {
    propertyType = 'HOUSE';
  } else if (
    /\bland\b/i.test(msg)
  ) {
    propertyType = 'LAND';
  } else if (
    /\boffice\b/i.test(msg)
  ) {
    propertyType = 'OFFICE';
  } else if (
    /\bshop\b/i.test(msg)
  ) {
    propertyType = 'SHOP';
  } else if (
    /\bcommercial\b/i.test(msg)
  ) {
    propertyType = 'COMMERCIAL';
  }

  // -------------------------
  // Bedrooms
  // -------------------------

  const bedMatch =
    msg.match(/\b(\d+)\s*[- ]?(?:bed|bedroom|bedrooms|br)\b/i);

  const bedrooms =
    bedMatch
      ? parseInt(bedMatch[1], 10)
      : null;

  // -------------------------
  // Budget
  // -------------------------

  let budgetMin = null;
  let budgetMax = null;
  let currency = null;

  const rangeBudgetMatch = msg.match(
    /(?:₦|ngn|n)?\s*(\d+(?:\.\d+)?)\s*(?:m|million)?\s*(?:-|to|and)\s*(?:₦|ngn|n)?\s*(\d+(?:\.\d+)?)\s*(?:m|million)/i
  );

  const singleBudgetMatch = msg.match(
    /(?:budget(?:\s+is|\s+of)?|₦|ngn)\s*(?:₦|ngn|n)?\s*(\d+(?:\.\d+)?)\s*(m|million)?/i
  );

  if (rangeBudgetMatch) {
    const first = parseFloat(rangeBudgetMatch[1]);
    const second = parseFloat(rangeBudgetMatch[2]);

    budgetMin = first * 1000000;
    budgetMax = second * 1000000;
    currency = 'NGN';
  } else if (singleBudgetMatch) {
    let amount = parseFloat(singleBudgetMatch[1]);

    if (
      singleBudgetMatch[2] &&
      /m|million/i.test(singleBudgetMatch[2])
    ) {
      amount *= 1000000;
    }

    budgetMin = amount;
    budgetMax = amount;
    currency = 'NGN';
  }

  if (
    msg.includes('₦') ||
    /\bngn\b/i.test(msg) ||
    /\bnaira\b/i.test(msg)
  ) {
    currency = 'NGN';
  }

  // -------------------------
  // Timeline
  // -------------------------

  let timeline = null;

  if (
    /\b(immediately|urgent|urgently|as soon as possible|asap)\b/i.test(msg)
  ) {
    timeline = 'IMMEDIATELY';
  } else if (
    /\b(within|next)\s*(?:1|one)\s*month\b/i.test(msg)
  ) {
    timeline = 'WITHIN_1_MONTH';
  } else if (
    /\b(within|next)\s*(?:3|three)\s*months?\b/i.test(msg)
  ) {
    timeline = 'WITHIN_3_MONTHS';
  } else if (
    /\b(within|next)\s*(?:6|six)\s*months?\b/i.test(msg)
  ) {
    timeline = 'WITHIN_6_MONTHS';
  } else if (
    /\b(researching|just looking|looking around|exploring options)\b/i.test(msg)
  ) {
    timeline = 'RESEARCHING';
  }

  // -------------------------
  // Location
  // -------------------------

  let location = null;

  const locationMatch = originalMessage.match(
    /\b(?:in|around|at)\s+([A-Za-z][A-Za-z\s'-]*(?:,\s*[A-Za-z][A-Za-z\s'-]*)?)(?=\.|,?\s+(?:my|with|and|budget|within|for|i'd|i\s+want)|$)/i
  );

  if (locationMatch) {
    location = locationMatch[1].trim();
  }

  // -------------------------
  // Email
  // -------------------------

  const emailMatch = originalMessage.match(
    /\b[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}\b/i
  );

  const email =
    emailMatch
      ? emailMatch[0]
      : null;

  // -------------------------
  // Phone
  // -------------------------

  let phone = null;

  const phoneMatch = originalMessage.match(
    /(?:\+234|0)\d{10}\b/
  );

  if (phoneMatch) {
    phone = phoneMatch[0];
  }

  // -------------------------
  // Confidence
  // -------------------------

  const explicitValues = [
    transactionType,
    propertyType,
    bedrooms,
    location,
    budgetMin,
    budgetMax,
    timeline,
    email,
    phone,
  ].filter(
    value =>
      value !== null &&
      value !== undefined
  ).length;

  const confidence =
    explicitValues >= 4
      ? 0.9
      : explicitValues >= 2
        ? 0.8
        : explicitValues === 1
          ? 0.7
          : 0;

  const fallback = {
    transaction_type: transactionType,
    property_type: propertyType,
    bedrooms,
    location,
    budget_min: budgetMin,
    budget_max: budgetMax,
    currency,
    timeline,
    customer_name: null,
    email,
    phone,
    confidence,
  };

  return [
    {
      json: {
        ok: true,
        extraction: fallback,
        fallback_used: true,
        parse_error: error.message,
      },
    },
  ];
}

const x = $json.extraction || {};

// --------------------------------------------------
// MAYVEE allowed values
// --------------------------------------------------

const enums = {
  transaction_type: [
    'BUY',
    'RENT',
    'SELL',
    'BUILD',
    'INVEST',
    'ENQUIRY'
  ],

  property_type: [
    'APARTMENT',
    'HOUSE',
    'LAND',
    'OFFICE',
    'SHOP',
    'COMMERCIAL',
    'OTHER'
  ],

  timeline: [
    'IMMEDIATELY',
    'WITHIN_1_MONTH',
    'WITHIN_3_MONTHS',
    'WITHIN_6_MONTHS',
    'RESEARCHING'
  ]
};

// --------------------------------------------------
// Validate enums
// --------------------------------------------------

for (const [key, allowedValues] of Object.entries(enums)) {
  const value = x[key];

  if (
    value !== null &&
    value !== undefined &&
    !allowedValues.includes(value)
  ) {
    return [
      {
        json: {
          ok: false,
          error: {
            code: 'AI_ERROR',
            message: `Invalid ${key} value`,
            value
          }
        }
      }
    ];
  }
}

// --------------------------------------------------
// Validate bedrooms
// --------------------------------------------------

if (
  x.bedrooms !== null &&
  x.bedrooms !== undefined
) {
  const bedrooms = Number(x.bedrooms);

  if (
    !Number.isInteger(bedrooms) ||
    bedrooms < 0 ||
    bedrooms > 50
  ) {
    return [
      {
        json: {
          ok: false,
          error: {
            code: 'AI_ERROR',
            message: 'Invalid bedrooms value',
            value: x.bedrooms
          }
        }
      }
    ];
  }
}

// --------------------------------------------------
// Validate confidence
// --------------------------------------------------

const confidence = Number(x.confidence ?? 0);

if (
  !Number.isFinite(confidence) ||
  confidence < 0 ||
  confidence > 1
) {
  return [
    {
      json: {
        ok: false,
        error: {
          code: 'AI_ERROR',
          message: 'Invalid confidence value',
          value: x.confidence
        }
      }
    }
  ];
}

// --------------------------------------------------
// Numeric helper
// --------------------------------------------------

const toNumberOrNull = (value) => {
  if (
    value === null ||
    value === undefined ||
    value === ''
  ) {
    return null;
  }

  const number = Number(value);

  return Number.isFinite(number)
    ? number
    : null;
};

const budgetMin = toNumberOrNull(x.budget_min);
const budgetMax = toNumberOrNull(x.budget_max);

// --------------------------------------------------
// Validate budgets
// --------------------------------------------------

if (
  x.budget_min !== null &&
  x.budget_min !== undefined &&
  x.budget_min !== '' &&
  budgetMin === null
) {
  return [
    {
      json: {
        ok: false,
        error: {
          code: 'AI_ERROR',
          message: 'Invalid budget_min value',
          value: x.budget_min
        }
      }
    }
  ];
}

if (
  x.budget_max !== null &&
  x.budget_max !== undefined &&
  x.budget_max !== '' &&
  budgetMax === null
) {
  return [
    {
      json: {
        ok: false,
        error: {
          code: 'AI_ERROR',
          message: 'Invalid budget_max value',
          value: x.budget_max
        }
      }
    }
  ];
}

if (
  budgetMin !== null &&
  budgetMax !== null &&
  budgetMin > budgetMax
) {
  return [
    {
      json: {
        ok: false,
        error: {
          code: 'AI_ERROR',
          message: 'budget_min cannot be greater than budget_max',
          value: {
            budget_min: budgetMin,
            budget_max: budgetMax
          }
        }
      }
    }
  ];
}

// --------------------------------------------------
// Validate currency
// --------------------------------------------------

let currency = x.currency ?? null;

if (currency !== null && currency !== undefined) {
  currency = String(currency).trim().toUpperCase();

  if (currency.length === 0) {
    currency = null;
  }
}

// --------------------------------------------------
// Clean string helper
// --------------------------------------------------

const cleanString = (value) => {
  if (
    value === null ||
    value === undefined
  ) {
    return null;
  }

  const text = String(value).trim();

  return text.length
    ? text
    : null;
};

// --------------------------------------------------
// Return validated extraction
// --------------------------------------------------

return [
  {
    json: {
      ok: true,

      extraction: {
        transaction_type:
          x.transaction_type ?? null,

        property_type:
          x.property_type ?? null,

        bedrooms:
          x.bedrooms === null ||
          x.bedrooms === undefined
            ? null
            : Number(x.bedrooms),

        location:
          cleanString(x.location),

        budget_min:
          budgetMin,

        budget_max:
          budgetMax,

        currency:
          currency,

        timeline:
          x.timeline ?? null,

        customer_name:
          cleanString(x.customer_name),

        email:
          cleanString(x.email),

        phone:
          cleanString(x.phone),

        confidence
      }
    }
  }
];

const existing=$('Get Lead').item.json.data || $('Get Lead').item.json.lead || $('Get Lead').item.json;
const x=$json.extraction; const update={};
for(const k of ['transaction_type','property_type','bedrooms','location','budget_min','budget_max','currency','timeline','customer_name','email','phone']){if(x[k]!==null&&x[k]!==undefined&&x[k]!=='')update[k]=x[k];}
return [{json:{lead_id:$('Normalize Event').item.json.lead_id,message_id:$('Normalize Event').item.json.message_id,conversation_id:$('Normalize Event').item.json.conversation_id,extraction:x,existing_lead:existing,lead_update:update}}];

const b=$('Build Lead Update').item.json;
const missing=['transaction_type','property_type','location','budget','bedrooms','timeline','contact'].filter(k=>{if(k==='budget')return b.lead_update.budget_min===undefined&&b.lead_update.budget_max===undefined&&b.existing_lead?.budget_min==null&&b.existing_lead?.budget_max==null;if(k==='contact')return !(b.existing_lead?.email||b.existing_lead?.phone||b.extraction.email||b.extraction.phone);return b.lead_update[k]===undefined&&!b.existing_lead?.[k];});
const system=`Generate a concise professional customer-facing response for MAYVEE Homes & Properties. Use only known lead information. Never claim a property is available, quote a price, or promise an outcome unless verified. Ask only the most useful missing question using this priority: transaction type, property type, location, budget, bedrooms, timeline, contact details. If no important field is missing, acknowledge the requirements and say the team can help narrow suitable options. Do not mention internal systems, AI, scores, or workflow.
Lead update: ${JSON.stringify(b.lead_update)}
Existing lead: ${JSON.stringify(b.existing_lead)}
Missing fields: ${JSON.stringify(missing)}
Latest customer message: ${JSON.stringify($('Build AI Context').item.json.current_message)}`;
return [{json:{...b,missing_fields:missing,ai_payload:{model:($env.LLM_MODEL || $env.GROQ_MODEL || 'openai/gpt-oss-120b'),temperature:0.3,messages:[{role:'system',content:system},{role:'user',content:$('Build AI Context').item.json.current_message}]}}}];

const r = $json;
const text = r.output_text || r.text || r.content || r.response || r.choices?.[0]?.message?.content || r.choices?.[0]?.text;
if (!text || typeof text !== 'string') {
  const upd = $('Build Lead Update').item.json;
  const lead = upd.lead_update || upd.extraction || {};
  let reply = "Hello from MAYVEE Homes & Properties! Thank you for your enquiry";
  if (lead.property_type) reply += ` regarding a ${lead.property_type.toLowerCase()}`;
  if (lead.bedrooms) reply += ` with ${lead.bedrooms} bedrooms`;
  if (lead.location) reply += ` in ${lead.location}`;
  if (lead.budget_max) reply += ` around ₦${(lead.budget_max / 1000000).toLocaleString()}M`;
  reply += ". Our sales advisory team has verified matching listings available and will share full options with you shortly. Could you also share your preferred contact phone number?";
  return [{ json: { ok: true, response: reply } }];
}
return [{ json: { ok: true, response: text.trim() } }];
